from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from windows import Sample, minute_bucket_starts, rollup_minute_totals, sanity_check_non_negative


def load_samples_from_jsonl(path: Path) -> list[Sample]:
    rows: list[Sample] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        obj: dict[str, Any] = json.loads(line)
        rows.append(Sample(int(obj["ts_ms"]), float(obj["value"])))
    return rows


def run_nightly_rollup_file(path: Path, epoch_start: int, epoch_end: int) -> list[tuple[int, float]]:
    samples = load_samples_from_jsonl(path)
    totals = rollup_minute_totals(samples, epoch_start, epoch_end)
    sanity_check_non_negative(totals)
    return totals


def format_minute_key(ms: int) -> str:
    return f"minute={ms}"


def attach_metadata(
    totals: list[tuple[int, float]],
    source: str,
    region: str,
) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for start_ms, value in totals:
        out.append(
            {
                "start_ms": start_ms,
                "value": value,
                "source": source,
                "region": region,
                "key": format_minute_key(start_ms),
            }
        )
    return out


def estimate_cost_rows(totals: list[tuple[int, float]], cost_per_point: float) -> float:
    acc = 0.0
    for _, v in totals:
        acc += max(v, 0.0) * cost_per_point
    return round(acc, 4)


def clip_rollups_to_ceiling(totals: list[tuple[int, float]], ceiling: float) -> list[tuple[int, float]]:
    clipped: list[tuple[int, float]] = []
    for t, v in totals:
        clipped.append((t, min(v, ceiling)))
    return clipped


def merge_rollups_by_minute(
    primary: list[tuple[int, float]],
    secondary: list[tuple[int, float]],
) -> list[tuple[int, float]]:
    idx: dict[int, float] = {}
    for t, v in primary:
        idx[t] = idx.get(t, 0.0) + v
    for t, v in secondary:
        idx[t] = idx.get(t, 0.0) + v
    return sorted(idx.items(), key=lambda kv: kv[0])


def window_for_now_ms(now_ms: int) -> tuple[int, int]:
    return minute_bucket_starts(now_ms)


def summarize_peaks(totals: list[tuple[int, float]]) -> dict[str, float]:
    if not totals:
        return {"max": 0.0, "min": 0.0, "avg": 0.0}
    vals = [v for _, v in totals]
    return {"max": max(vals), "min": min(vals), "avg": sum(vals) / len(vals)}


def export_prometheus_style(totals: list[tuple[int, float]], metric: str) -> str:
    lines: list[str] = []
    for t, v in totals:
        lines.append(f"{metric}{{start=\"{t}\"}} {v}")
    return "\n".join(lines)

