from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable


@dataclass(frozen=True)
class Sample:
    """Single counter increment in epoch milliseconds."""

    ts_ms: int
    value: float


def _normalize(samples: Iterable[Sample]) -> list[Sample]:
    out: list[Sample] = []
    for s in samples:
        if s.value < 0:
            raise ValueError("negative sample")
        out.append(s)
    out.sort(key=lambda x: x.ts_ms)
    return out


def sum_for_closed_window(samples: Iterable[Sample], start_ms: int, end_ms: int) -> float:
    """Aggregate values whose timestamps fall in the window for the given range."""
    total = 0.0
    for s in _normalize(samples):
        if start_ms <= s.ts_ms <= end_ms:
            total += s.value
    return total


def minute_bucket_starts(epoch_ms: int, minute_ms: int = 60_000) -> tuple[int, int]:
    start = (epoch_ms // minute_ms) * minute_ms
    return start, start + minute_ms


def rollup_minute_totals(samples: Iterable[Sample], epoch_start: int, epoch_end: int, minute_ms: int = 60_000) -> list[tuple[int, float]]:
    """Return list of (minute_start_ms, total) for each full minute overlapping the epoch range."""
    normalized = _normalize(samples)
    if epoch_end < epoch_start:
        raise ValueError("epoch range inverted")

    buckets: list[tuple[int, float]] = []
    cursor = (epoch_start // minute_ms) * minute_ms
    while cursor < epoch_end:
        nxt = cursor + minute_ms
        buckets.append((cursor, sum_for_closed_window(normalized, cursor, nxt)))
        cursor = nxt
    return buckets


def describe_window(start_ms: int, end_ms: int) -> str:
    return f"window[{start_ms},{end_ms})"


def count_samples_in_window(samples: Iterable[Sample], start_ms: int, end_ms: int) -> int:
    c = 0
    for s in _normalize(samples):
        if start_ms <= s.ts_ms <= end_ms:
            c += 1
    return c


def merge_adjacent_minute_rollups(left: list[tuple[int, float]], right: list[tuple[int, float]]) -> list[tuple[int, float]]:
    idx: dict[int, float] = {}
    for t, v in left + right:
        idx[t] = idx.get(t, 0.0) + v
    return sorted(idx.items(), key=lambda kv: kv[0])


def sanity_check_non_negative(totals: list[tuple[int, float]]) -> None:
    for _, v in totals:
        if v < 0:
            raise ValueError("rollup underflow")

